import { useState } from "react";

export default function App() {
  const [n, setN] = useState(0);
  return (
    <div>
      <span id="n">{n}</span>
      <button id="inc" onClick={() => setN(n + 1)}>+</button>
      <button id="dec" onClick={() => setN(n - 1)}>−</button>
      <button id="reset" onClick={() => setN(0)}>Reset</button>
    </div>
  );
}
